securityRules.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAuthenticated() {
      return request.auth != null;
    }
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }
    match /{document=**} {
      allow read, write: if false;
    }
    match /users/{userId} {
      allow read, write: if isOwner(userId);
    }
    match /users/{userId}/entries/{entryId} {
      allow read, write: if isOwner(userId);
    }
    match /shares/{shareId} {
      allow create: if isAuthenticated() && request.resource.data.sharerUid == request.auth.uid;
      allow read: if isAuthenticated() && (resource.data.sharerUid == request.auth.uid || (resource.data.granteeUid == request.auth.uid && resource.data.expiresAt > request.time && resource.data.revoked == false));
      allow update: if isAuthenticated() && resource.data.sharerUid == request.auth.uid;
      allow delete: if isAuthenticated() && resource.data.sharerUid == request.auth.uid;
    }
  }
}
